data = json.load(open(p))
ids = {r["id"] for r in ROWS}
n = 0
for pid, (ages, txt) in CATAGES.items():
    if pid in ids:
        data[pid] = {**ages, "src": (txt if txt.startswith("сайт") else Y + txt) + "; 12.11.2026"}
        n += 1
json.dump(data, open(p, "w"), ensure_ascii=False, indent=1)
print("cat_ages:", n)
